#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // This is a simple implementation and may not cover all markdown features
    // For a more robust solution, consider using a dedicated markdown library
    // like libmarkdown or markdown-c.

    std::string html;
    std::stringstream ss(markdown);
    std::string line;
    while (std::getline(ss, line)) {
        html += line + "\n";
    }
    return html;
}

int main() {
    std::string markdown = "# Hello, World!\nThis is a markdown example.\n";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
